// Calculate date 7 days ago in ISO format
const now = new Date();
const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

return [{
  json: {
    since: sevenDaysAgo.toISOString(),
    now: now.toISOString(),
    repo: $env.GITHUB_REPO || 'owner/repo',
    language: $env.LANGUAGE || 'EN'
  }
}];

// Gather data from all three GitHub API calls
const commitsRaw = $('Fetch Commits').all();
const issuesRaw = $('Fetch Closed Issues').all();
const prsRaw = $('Fetch Merged PRs').all();
const vars = $('Set Date Range & Variables').first().json;

const since = vars.since;
const language = vars.language || 'EN';
const repo = vars.repo;

// Process commits
const commits = [];
for (const item of commitsRaw) {
  if (Array.isArray(item.json)) {
    for (const c of item.json) {
      commits.push({
        sha: c.sha ? c.sha.substring(0, 7) : 'unknown',
        message: c.commit?.message?.split('\n')[0] || 'No message',
        author: c.commit?.author?.name || c.author?.login || 'Unknown',
        date: c.commit?.author?.date || ''
      });
    }
  } else if (item.json.sha) {
    commits.push({
      sha: item.json.sha.substring(0, 7),
      message: item.json.commit?.message?.split('\n')[0] || 'No message',
      author: item.json.commit?.author?.name || item.json.author?.login || 'Unknown',
      date: item.json.commit?.author?.date || ''
    });
  }
}

// Process closed issues (filter out PRs which also appear as issues)
const issues = [];
for (const item of issuesRaw) {
  if (Array.isArray(item.json)) {
    for (const i of item.json) {
      if (!i.pull_request) {
        issues.push({
          number: i.number,
          title: i.title,
          labels: (i.labels || []).map(l => l.name).join(', '),
          closed_at: i.closed_at
        });
      }
    }
  } else if (item.json.number && !item.json.pull_request) {
    issues.push({
      number: item.json.number,
      title: item.json.title,
      labels: (item.json.labels || []).map(l => l.name).join(', '),
      closed_at: item.json.closed_at
    });
  }
}

// Process merged PRs (only those actually merged within the period)
const sinceDate = new Date(since);
const prs = [];
for (const item of prsRaw) {
  if (Array.isArray(item.json)) {
    for (const p of item.json) {
      if (p.merged_at && new Date(p.merged_at) >= sinceDate) {
        prs.push({
          number: p.number,
          title: p.title,
          author: p.user?.login || 'Unknown',
          merged_at: p.merged_at
        });
      }
    }
  } else if (item.json.merged_at && new Date(item.json.merged_at) >= sinceDate) {
    prs.push({
      number: item.json.number,
      title: item.json.title,
      author: item.json.user?.login || 'Unknown',
      merged_at: item.json.merged_at
    });
  }
}

// Build the prompt
let prompt = `Repository: ${repo}\nPeriod: ${since} to ${vars.now}\n\n`;

prompt += `## Commits (${commits.length} total)\n`;
for (const c of commits.slice(0, 50)) {
  prompt += `- [${c.sha}] ${c.message} (by ${c.author})\n`;
}
if (commits.length > 50) prompt += `... and ${commits.length - 50} more commits\n`;

prompt += `\n## Closed Issues (${issues.length} total)\n`;
for (const i of issues.slice(0, 30)) {
  prompt += `- #${i.number}: ${i.title}${i.labels ? ` [${i.labels}]` : ''}\n`;
}
if (issues.length > 30) prompt += `... and ${issues.length - 30} more issues\n`;

prompt += `\n## Merged Pull Requests (${prs.length} total)\n`;
for (const p of prs.slice(0, 30)) {
  prompt += `- PR #${p.number}: ${p.title} (by ${p.author})\n`;
}
if (prs.length > 30) prompt += `... and ${prs.length - 30} more PRs\n`;

const langInstruction = language === 'FR'
  ? 'IMPORTANT: Write the entire summary in French.'
  : 'Write the summary in English.';

return [{
  json: {
    prompt,
    language,
    langInstruction,
    repo,
    commitCount: commits.length,
    issueCount: issues.length,
    prCount: prs.length
  }
}];

