const response = $input.first().json;
const vars = $('Set Date Range & Variables').first().json;

let summary = '';

if (response.content && response.content.length > 0) {
  summary = response.content[0].text;
} else if (response.error) {
  summary = `Error from Claude API: ${JSON.stringify(response.error)}`;
} else {
  summary = 'No summary could be generated. Please check the Claude API response.';
}

// Truncate for Discord embed limit (4096 chars for description)
const maxLen = 4000;
if (summary.length > maxLen) {
  summary = summary.substring(0, maxLen) + '\n\n... (truncated)';
}

return [{
  json: {
    summary,
    repo: vars.repo,
    period: `${new Date(vars.since).toLocaleDateString()} - ${new Date(vars.now).toLocaleDateString()}`,
    commitCount: $('Combine & Format Data').first().json.commitCount,
    issueCount: $('Combine & Format Data').first().json.issueCount,
    prCount: $('Combine & Format Data').first().json.prCount
  }
}];

